window.__programmeIndexChunk("statements",{"a1e4ac64561b7713230e48193558fdee2cb364facfa7b95c5c05255615cce454":{"markdown":"**Lemma 5.2.** Suppose an oriented real rank-\\(d\\) bundle over a closed oriented \\(d\\)-manifold has a section with finitely many isolated zeros. Its Euler number is the sum of its local degrees. A zero with invertible derivative contributes the sign of that derivative's real determinant.","html":"<p><strong>Lemma 5.2.<\/strong> Suppose an oriented real rank-<span class=\"math\" data-tex=\"\\(d\\)\">\\(d\\)<\/span> bundle over a closed oriented <span class=\"math\" data-tex=\"\\(d\\)\">\\(d\\)<\/span>-manifold has a section with finitely many isolated zeros. Its Euler number is the sum of its local degrees. A zero with invertible derivative contributes the sign of that derivative's real determinant.<\/p>\n","source":"docs/courses/DG-CHAR/chern-classes-and-the-integral-universal-ring.md","start_offset":21693,"end_offset":21983,"label":"Lemma 5.2","extraction_boundary":"numbered_statement_boundary"},"a1e2106676b9f50658044ed8ef309e3318781ed110c6e460c6e59409f8c6870c":{"markdown":"**Exercise O.4 — Hard.** Explain why bounded exponent, rather than merely two-primary torsion, is essential in the first-fibre argument G.1. Give a nonzero two-primary torsion group whose mod-two tensor product is zero.","html":"<p><strong>Exercise O.4 — Hard.<\/strong> Explain why bounded exponent, rather than merely two-primary torsion, is essential in the first-fibre argument G.1. Give a nonzero two-primary torsion group whose mod-two tensor product is zero.<\/p>\n","source":"docs/courses/DG-CHAR/stiefel-whitney-numbers-and-unoriented-bordism.md","start_offset":101306,"end_offset":101527,"label":"Exercise O.4","extraction_boundary":"numbered_statement_boundary"},"a1759ff3f0f44b2217c61e692907b8738dc33e82d954bd0d6c1049b40685b75b":{"markdown":"**Lemma 2.2.** If \\(w\\ne e\\) and \\(m>\\ell(w)\\), where \\(\\ell\\) is reduced word length, then\n\\[\nt^mwt^{-m}\n\\tag{10}\n\\]\nis either a nonzero power of \\(t\\), or starts with \\(a\\) and ends with \\(a^{-1}\\).","html":"<p><strong>Lemma 2.2.<\/strong> If <span class=\"math\" data-tex=\"\\(w\\ne e\\)\">\\(w\\ne e\\)<\/span> and <span class=\"math\" data-tex=\"\\(m&gt;\\ell(w)\\)\">\\(m&gt;\\ell(w)\\)<\/span>, where <span class=\"math\" data-tex=\"\\(\\ell\\)\">\\(\\ell\\)<\/span> is reduced word length, then\n<span class=\"math display\" data-tex=\"\\[\nt^mwt^{-m}\n\\tag{10}\n\\]\">\\[\nt^mwt^{-m}\n\\tag{10}\n\\]<\/span>\nis either a nonzero power of <span class=\"math\" data-tex=\"\\(t\\)\">\\(t\\)<\/span>, or starts with <span class=\"math\" data-tex=\"\\(a\\)\">\\(a\\)<\/span> and ends with <span class=\"math\" data-tex=\"\\(a^{-1}\\)\">\\(a^{-1}\\)<\/span>.<\/p>\n","source":"docs/courses/OA-APPROX/src/free-group-norm-averaging.md","start_offset":10265,"end_offset":10467,"label":"Lemma 2.2","extraction_boundary":"numbered_statement_boundary"},"a15f532d79a48170d9993340da456d51b99f019e9e2fe801af4b25d6650c0c38":{"markdown":"**Theorem 1.1.** There is a C\\*-algebra \\(A\\) with compatible maps \\(\\iota_n:A_n\\to A\\), dense union of their ranges, and\n\\[\n\\|\\iota_n(a)\\|=\\lim_{m\\to\\infty}\\|\\phi_{m,n}(a)\\|. \\tag{1}\n\\]\nEvery compatible family of \\*-homomorphisms \\(\\psi_n:A_n\\to B\\) extends uniquely to a \\*-homomorphism \\(A\\to B\\). If all connecting maps are injective, all \\(\\iota_n\\) are isometric.","html":"<p><strong>Theorem 1.1.<\/strong> There is a C*-algebra <span class=\"math\" data-tex=\"\\(A\\)\">\\(A\\)<\/span> with compatible maps <span class=\"math\" data-tex=\"\\(\\iota_n:A_n\\to A\\)\">\\(\\iota_n:A_n\\to A\\)<\/span>, dense union of their ranges, and\n<span class=\"math display\" data-tex=\"\\[\n\\|\\iota_n(a)\\|=\\lim_{m\\to\\infty}\\|\\phi_{m,n}(a)\\|. \\tag{1}\n\\]\">\\[\n\\|\\iota_n(a)\\|=\\lim_{m\\to\\infty}\\|\\phi_{m,n}(a)\\|. \\tag{1}\n\\]<\/span>\nEvery compatible family of *-homomorphisms <span class=\"math\" data-tex=\"\\(\\psi_n:A_n\\to B\\)\">\\(\\psi_n:A_n\\to B\\)<\/span> extends uniquely to a *-homomorphism <span class=\"math\" data-tex=\"\\(A\\to B\\)\">\\(A\\to B\\)<\/span>. If all connecting maps are injective, all <span class=\"math\" data-tex=\"\\(\\iota_n\\)\">\\(\\iota_n\\)<\/span> are isometric.<\/p>\n","source":"docs/courses/OA-APPROX/src/infinite-tensor-products.md","start_offset":3937,"end_offset":4308,"label":"Theorem 1.1","extraction_boundary":"numbered_statement_boundary"},"a1436829f8a4b1a61710a54446074b1e8c616692bfb4d7a9c0e5a31442823744":{"markdown":"**Problem.** In the proof of (K14), why is it insufficient to use (K2) only for the original action?","html":"<p><strong>Problem.<\/strong> In the proof of (K14), why is it insufficient to use (K2) only for the original action?<\/p>\n","source":"docs/courses/OA-FLOW/src/OA-FLOW-L115.md","start_offset":34013,"end_offset":34115,"label":null,"extraction_boundary":"all_numbered_statements_in_bound_passage"},"a1fee8fb979d895a78a8c20d11205dcd6d23e1ce049084108cd3a63d8b43f6e6":{"markdown":"**Problem.** If \\(U\\) is reducible and \\(0\\ne x\\in M_\\alpha(U)\\), must every component \\(xr_j\\) of this particular multiplier be nonzero, where \\((r_j)\\) are the irreducible summand projections?","html":"<p><strong>Problem.<\/strong> If <span class=\"math\" data-tex=\"\\(U\\)\">\\(U\\)<\/span> is reducible and <span class=\"math\" data-tex=\"\\(0\\ne x\\in M_\\alpha(U)\\)\">\\(0\\ne x\\in M_\\alpha(U)\\)<\/span>, must every component <span class=\"math\" data-tex=\"\\(xr_j\\)\">\\(xr_j\\)<\/span> of this particular multiplier be nonzero, where <span class=\"math\" data-tex=\"\\((r_j)\\)\">\\((r_j)\\)<\/span> are the irreducible summand projections?<\/p>\n","source":"docs/courses/OA-FLOW/src/OA-FLOW-L132.md","start_offset":24044,"end_offset":24240,"label":null,"extraction_boundary":"all_numbered_statements_in_bound_passage"},"a1507e8ef662d4a1b4369d4520b8dda3afc524bc24d3e9725f582d65652f0dd2":{"markdown":"**Lemma 2.1 (compact uniform control).** Suppose \\(D_j\\) are nonnegative measurable functions on a bounded interval \\(I\\), decreasing to zero almost everywhere, with \\(\\int_I D_j\\to0\\). Given \\(\\varepsilon>0\\) and a prescribed null set \\(N\\), there is a compact \\(K\\subset I\\setminus N\\) with \\(|I\\setminus K|<\\varepsilon\\) on which \\(D_j\\to0\\) uniformly.","html":"<p><strong>Lemma 2.1 (compact uniform control).<\/strong> Suppose <span class=\"math\" data-tex=\"\\(D_j\\)\">\\(D_j\\)<\/span> are nonnegative measurable functions on a bounded interval <span class=\"math\" data-tex=\"\\(I\\)\">\\(I\\)<\/span>, decreasing to zero almost everywhere, with <span class=\"math\" data-tex=\"\\(\\int_I D_j\\to0\\)\">\\(\\int_I D_j\\to0\\)<\/span>. Given <span class=\"math\" data-tex=\"\\(\\varepsilon&gt;0\\)\">\\(\\varepsilon&gt;0\\)<\/span> and a prescribed null set <span class=\"math\" data-tex=\"\\(N\\)\">\\(N\\)<\/span>, there is a compact <span class=\"math\" data-tex=\"\\(K\\subset I\\setminus N\\)\">\\(K\\subset I\\setminus N\\)<\/span> with <span class=\"math\" data-tex=\"\\(|I\\setminus K|&lt;\\varepsilon\\)\">\\(|I\\setminus K|&lt;\\varepsilon\\)<\/span> on which <span class=\"math\" data-tex=\"\\(D_j\\to0\\)\">\\(D_j\\to0\\)<\/span> uniformly.<\/p>\n","source":"docs/courses/OA-FLOW/src/OA-FLOW-SEC.md","start_offset":9479,"end_offset":9836,"label":"Lemma 2.1","extraction_boundary":"all_numbered_statements_in_bound_passage"},"a159d2ce152180b740cec72b976aa1118b48e0dceb43de70fb71afee0c968798":{"markdown":"**Theorem.** Let \\(h_n,h\\) be the positive affiliated densities of normal semifinite weights on the same algebra, with\n\\(\\theta_s(h_n)=e^{-s}h_n\\) and \\(\\theta_s(h)=e^{-s}h\\).\nThe weights may have kernels or be zero. Suppose \\(h_n\\to h\\) in the strong resolvent sense in a faithful normal representation of \\(C\\). Write\n\\[\n e_n=s(h_n),\\qquad e=s(h),\\qquad\n \\kappa_n(1)=e_n,\\quad\\kappa(1)=e.\n\\]\nThese are the supported normal coordinates of [SCW5](OA-FLOW-SCW.md#scw-5); a bounded spectral function is zero on the complementary kernel. Then\n\\[\n \\boxed{\\quad\n \\kappa_n(f)\\longrightarrow\\kappa(f)\n \\ \\hbox{sigma-strong-star for every }f\\in L^\\infty(\\mathbb R,dq)\n \\quad\\Longleftrightarrow\\quad\n e_n\\longrightarrow e\\ \\hbox{strongly}.\n \\quad}\\tag{WCH14}\n\\]\nIn particular, the scalar conclusion holds for one fixed support corner. It also holds whenever the limit density is faithful, even if some approximating densities have kernels; the proof below shows that support convergence is then automatic. No dominance, finite weight mass, separability or normal joint tensor map is required.\n\nNecessity follows by taking \\(f=1\\). For sufficiency assume the support projections converge strongly. On this uniformly bounded family, strong convergence is equivalent to convergence of all normal positive seminorms: the normal vector-series representation of [CP4 and CP6](OA-FLOW-CP.md#oa-flow.cp.4) gives one implication by truncating a summable series, and vector functionals give the other. Adjoint convergence is the same assertion for these selfadjoint projections.\n\nWe give the needed uniform absolute continuity, including its dependence on the test functional. Fix \\(\\omega\\in C_*^+\\). The path \\(s\\mapsto\\omega\\circ\\theta_s\\) is norm-continuous. One direct proof uses the reference regular core representation, where \\(\\theta_s\\) is implemented by the strongly continuous scalar multipliers \\(e^{-isr}\\). A vector functional changes in norm by at most\n\\((\\|U_s\\xi\\|+\\|\\xi\\|)\\|U_s\\xi-\\xi\\|\\).\nEvery normal positive functional is a sum of vector functionals with summable squared norms; a finite initial sum and its uniform norm tail prove the assertion for \\(\\omega\\). Transport through the normal core chart preserves that predual norm.\n\nChoose a nonnegative bounded compactly supported scalar function \\(g\\) with \\(\\int g(s)ds=1\\), supported sufficiently close to zero that\n\\[\n \\omega_g=\\int g(s)(\\omega\\circ\\theta_s)ds,\n \\qquad \\|\\omega_g-\\omega\\|<\\varepsilon.\n \\tag{WCH15}\n\\]\nThis is a Bochner integral in the predual: norm-continuity, compact support and boundedness give its existence. For every coordinate \\(\\kappa_j\\), including the limit one, let \\(\\mu_j(B)=\\omega(\\kappa_j(1_B))\\). These are finite measures of total mass \\(\\mu_j(\\mathbb R)=\\omega(e_j)\\le\\omega(1)\\), with \\(e_\\infty=e\\). They vanish on Lebesgue-null sets by normality. Equivariance and nonnegative scalar interchange give\n\\[\n \\begin{aligned}\n \\omega_g(\\kappa_j(1_B))\n &=\\int g(s)\\int 1_B(q+s)\\,d\\mu_j(q)\\,ds\\\\\n &\\le\\|g\\|_\\infty\\,|B|\\,\\omega(1).\n \\end{aligned}\\tag{WCH16}\n\\]\nBoth measures in the interchange are sigma-finite; one is finite and the other is Lebesgue measure. Thus\n\\[\n \\sup_j\\mu_j(B)\\le\\varepsilon+\\|g\\|_\\infty\\omega(1)|B|.\n \\tag{WCH17}\n\\]\nFor every prescribed bound \\(\\delta>0\\), first choose \\(\\varepsilon<\\delta/2\\), then make \\(|B|<\\delta/(2\\|g\\|_\\infty\\omega(1))\\). The zero functional needs no estimate. This proves uniform absolute continuity of the entire family of scalar spectral measures. It is the extra conclusion furnished by homogeneity; strong resolvent convergence alone does not imply it.\n\nIf \\(v\\in C_c(\\mathbb R)\\), the scalar function \\(x\\mapsto v(-\\log x)\\) on \\((0,\\infty)\\), extended by zero at zero, belongs to \\(C_0([0,\\infty))\\). Strong resolvent convergence therefore gives \\(\\kappa_n(v)\\to\\kappa(v)\\) strongly-star. The functional-calculus step has an explicit approximation proof. Extend \\(f(x)=v(-\\log x)\\) by zero on \\(( -\\infty,0]\\); compact support of \\(v\\) makes \\(f\\in C_0(\\mathbb R)\\). The Cayley unitaries \\(U_n=1-2i(h_n+i)^{-1}\\) converge strongly to \\(U=1-2i(h+i)^{-1}\\). Their adjoints converge strongly too, since \\((U_n^*-U^*)\\xi=U_n^*(U-U_n)U^*\\xi\\). The Cayley coordinate \\(x\\mapsto(x-i)/(x+i)\\) transports \\(f\\) to a continuous circle function \\(\\widehat f\\) with \\(\\widehat f(1)=0\\). The [proved Fejér approximation and unitary calculus](OA-FLOW-SF.md#oa-flow.sf.sb1) approximate \\(\\widehat f\\) uniformly by Laurent polynomials. Each polynomial in \\(U_n,U_n^*\\) converges strongly-star, and the uniform approximation bound is independent of \\(n\\). Consequently \\(f(h_n)=\\widehat f(U_n)\\to\\widehat f(U)=f(h)\\) strongly-star, which is exactly the assertion just used. Bounded strong convergence in a faithful normal representation also gives convergence for every normal positive seminorm: express that functional as a summable vector series and control its tail by the common operator bound.\n\nSupport convergence gives \\(\\mu_n(\\mathbb R)=\\omega(e_n)\\to\\omega(e)=\\mu(\\mathbb R)\\). The measures are therefore eventually tight. Given \\(\\varepsilon>0\\), choose \\(0\\le v\\le1\\) in \\(C_c\\) with\n\\(\\mu(v)>\\mu(\\mathbb R)-\\varepsilon\\). Increasing compact cutoffs provide such a function, including when \\(\\mu=0\\). For all sufficiently large \\(n\\), the preceding functional-calculus convergence gives\n\\(\\mu_n(v)>\\mu(v)-\\varepsilon\\), while\n\\(\\mu_n(\\mathbb R)<\\mu(\\mathbb R)+\\varepsilon\\).\nIf \\(\\operatorname{supp}v\\subset[-R,R]\\), then\n\\[\n \\mu_n(\\mathbb R\\setminus[-R,R])<3\\varepsilon.\n \\tag{WCH18}\n\\]\nThe limit measure satisfies the same bound. Only this eventual estimate is needed.\n\nThis also proves the stated automatic support convergence when \\(e=1\\), without assuming it in advance. For every \\(\\omega\\in C_*^+\\), choose a compact cutoff with\n\\(\\omega(\\kappa(v))>\\omega(1)-\\varepsilon\\). Since\n\\(0\\le\\kappa_n(v)\\le e_n\\), convergence on this continuous function gives\n\\(\\limsup_n\\omega(1-e_n)\\le\\varepsilon\\).\nLet \\(\\varepsilon\\downarrow0\\). Testing vector functionals proves \\(e_n\\to1\\) strongly, so the preceding tightness argument applies.\n\nNow fix \\(f\\in L^\\infty\\), represented with \\(|f|\\le K\\). On \\([-R,R]\\) approximate its values by a finite grid to obtain a simple function within \\(\\eta\\) uniformly. In each of its finitely many measurable level sets choose a compact subset; Lebesgue inner regularity makes the total discarded measure as small as desired. These compact sets are disjoint. Choose disjoint bounded open neighborhoods and continuous bump functions equal to one on the compact sets. The finite sum of the simple values times these bumps is a \\(v\\in C_c(\\mathbb R)\\) with \\(|v|\\le K\\), agreeing with the simple function on their union. Consequently \\(|f-v|\\le\\eta\\) off a measurable exceptional set \\(B\\subset[-R,R]\\), and \\(|B|\\) is arbitrarily small.\n\nEquations (WCH17)–(WCH18) give, uniformly for sufficiently large \\(n\\) and for the limit,\n\\[\n \\begin{aligned}\n \\|\\kappa_n(f-v)\\|_\\omega^2\n &=\\int|f-v|^2d\\mu_n\\\\\n &\\le\\eta^2\\omega(1)+4K^2\\mu_n(B)\n          +4K^2\\mu_n(\\mathbb R\\setminus[-R,R]).\n \\end{aligned}\\tag{WCH19}\n\\]\nHere \\(\\|x\\|_\\omega=\\omega(x^*x)^{1/2}\\). First choose the tail bound, then the exceptional measure, then \\(\\eta\\). The right side can be made arbitrarily small. The triangle inequality and the already proved convergence for \\(v\\) prove convergence for \\(f\\). Apply the same argument to \\(\\overline f\\) for the adjoint seminorms. This proves (WCH14) with all cutoffs and all normal functionals accounted for.\n\n\n**Why the support condition is necessary.** In the scalar core of [CORE9](OA-FLOW-CORE.md#core-9), use the positive Fourier coordinate \\(p\\):\n\\[\n C=L^\\infty(\\mathbb R,dp),\\qquad\n \\theta_s f(p)=f(p-s),\\qquad\n \\tau(f)=\\frac1{2\\pi}\\int e^{-p}f(p)\\,dp.\n\\]\nThe finite scalar weights \\(\\varphi_n(1)=1/n\\) have densities\n\\[\n h_n(p)=e^p/n,\\qquad h(p)=0,\\qquad\n e_n=1,\\quad e=0. \\tag{WCH14a}\n\\]\nEvery \\(h_n\\) is positive, faithful and homogeneous, and its full multiplication domain is dense by compact truncation. The zero limit is the density of the zero normal semifinite weight. On \\(L^2(\\mathbb R,dp)\\), the resolvent multipliers\n\\((e^p/n-i)^{-1}\\) converge pointwise to \\(i\\), and their absolute values are at most one. Scalar dominated convergence against each squared Hilbert vector proves strong resolvent convergence to zero. Nevertheless\n\\[\n \\kappa_n(f)(p)=f(\\log n-p),\\qquad\n \\kappa_0(f)=0,\\qquad\n \\kappa_n(1)-\\kappa_0(1)=1. \\tag{WCH14b}\n\\]\nThus even positive homogeneous measurable densities do not give the all-\\(L^\\infty\\) conclusion when their supports fail to converge. The measurability follows also from their finite functional masses in [MGI1](OA-FLOW-MGI.md#gi-finite-cut).\n\nThe loss is visible in one normal vector functional. Take the unit vector\n\\(\\xi=1_{[0,1]}\\) and set\n\\(\\mu_n(B)=\\langle\\kappa_n(1_B)\\xi,\\xi\\rangle\\).\nSubstitution \\(q=\\log n-p\\) gives\n\\[\n d\\mu_n(q)=1_{[\\log n-1,\\log n]}(q)\\,dq,\\qquad\n \\mu_n(\\mathbb R)=1,\\qquad \\mu_0=0. \\tag{WCH14c}\n\\]\nEvery compact coordinate set eventually has zero mass, while total mass stays one. Uniform absolute continuity (WCH17) still holds; tightness fails. These are vector spectral measures, not the canonical core trace.\n\n![Strong resolvent convergence to zero and the spectral mass retained by the nonzero supports.](../assets/canonical-cocycle-sections/support-continuity.png)\n\n*Figure 4.* The left panel shows the exact bounded multipliers \\((1+e^p/n)^{-1}\\) on a finite window; their strong limit is \\(1\\). The right panel shows the exact vector spectral measures (WCH14c), each of mass one on a translated unit interval, while the zero weight has mass zero. The full convergence proof is dominated convergence above, not a uniform estimate on the displayed window. Original [renderer](../assets/canonical-cocycle-sections/render_support_continuity.py), [exact data](../assets/canonical-cocycle-sections/support-continuity.json), [editable SVG](../assets/canonical-cocycle-sections/support-continuity.svg) and [terms](../assets/canonical-cocycle-sections/TERMS.md).\n\n<a id=\"wch-joint-continuity\"><\/a>","html":"<p><strong>Theorem.<\/strong> Let <span class=\"math\" data-tex=\"\\(h_n,h\\)\">\\(h_n,h\\)<\/span> be the positive affiliated densities of normal semifinite weights on the same algebra, with\n<span class=\"math\" data-tex=\"\\(\\theta_s(h_n)=e^{-s}h_n\\)\">\\(\\theta_s(h_n)=e^{-s}h_n\\)<\/span> and <span class=\"math\" data-tex=\"\\(\\theta_s(h)=e^{-s}h\\)\">\\(\\theta_s(h)=e^{-s}h\\)<\/span>.\nThe weights may have kernels or be zero. Suppose <span class=\"math\" data-tex=\"\\(h_n\\to h\\)\">\\(h_n\\to h\\)<\/span> in the strong resolvent sense in a faithful normal representation of <span class=\"math\" data-tex=\"\\(C\\)\">\\(C\\)<\/span>. Write\n<span class=\"math display\" data-tex=\"\\[\n e_n=s(h_n),\\qquad e=s(h),\\qquad\n \\kappa_n(1)=e_n,\\quad\\kappa(1)=e.\n\\]\">\\[\n e_n=s(h_n),\\qquad e=s(h),\\qquad\n \\kappa_n(1)=e_n,\\quad\\kappa(1)=e.\n\\]<\/span>\nThese are the supported normal coordinates of <a href=\"../courses/OA-FLOW/OA-FLOW-SCW.html#scw-5\">SCW5<\/a>; a bounded spectral function is zero on the complementary kernel. Then\n<span class=\"math display\" data-tex=\"\\[\n \\boxed{\\quad\n \\kappa_n(f)\\longrightarrow\\kappa(f)\n \\ \\hbox{sigma-strong-star for every }f\\in L^\\infty(\\mathbb R,dq)\n \\quad\\Longleftrightarrow\\quad\n e_n\\longrightarrow e\\ \\hbox{strongly}.\n \\quad}\\tag{WCH14}\n\\]\">\\[\n \\boxed{\\quad\n \\kappa_n(f)\\longrightarrow\\kappa(f)\n \\ \\hbox{sigma-strong-star for every }f\\in L^\\infty(\\mathbb R,dq)\n \\quad\\Longleftrightarrow\\quad\n e_n\\longrightarrow e\\ \\hbox{strongly}.\n \\quad}\\tag{WCH14}\n\\]<\/span>\nIn particular, the scalar conclusion holds for one fixed support corner. It also holds whenever the limit density is faithful, even if some approximating densities have kernels; the proof below shows that support convergence is then automatic. No dominance, finite weight mass, separability or normal joint tensor map is required.<\/p>\n<p>Necessity follows by taking <span class=\"math\" data-tex=\"\\(f=1\\)\">\\(f=1\\)<\/span>. For sufficiency assume the support projections converge strongly. On this uniformly bounded family, strong convergence is equivalent to convergence of all normal positive seminorms: the normal vector-series representation of <a href=\"../courses/OA-FLOW/OA-FLOW-CP.html#oa-flow.cp.4\">CP4 and CP6<\/a> gives one implication by truncating a summable series, and vector functionals give the other. Adjoint convergence is the same assertion for these selfadjoint projections.<\/p>\n<p>We give the needed uniform absolute continuity, including its dependence on the test functional. Fix <span class=\"math\" data-tex=\"\\(\\omega\\in C_*^+\\)\">\\(\\omega\\in C_*^+\\)<\/span>. The path <span class=\"math\" data-tex=\"\\(s\\mapsto\\omega\\circ\\theta_s\\)\">\\(s\\mapsto\\omega\\circ\\theta_s\\)<\/span> is norm-continuous. One direct proof uses the reference regular core representation, where <span class=\"math\" data-tex=\"\\(\\theta_s\\)\">\\(\\theta_s\\)<\/span> is implemented by the strongly continuous scalar multipliers <span class=\"math\" data-tex=\"\\(e^{-isr}\\)\">\\(e^{-isr}\\)<\/span>. A vector functional changes in norm by at most\n<span class=\"math\" data-tex=\"\\((\\|U_s\\xi\\|+\\|\\xi\\|)\\|U_s\\xi-\\xi\\|\\)\">\\((\\|U_s\\xi\\|+\\|\\xi\\|)\\|U_s\\xi-\\xi\\|\\)<\/span>.\nEvery normal positive functional is a sum of vector functionals with summable squared norms; a finite initial sum and its uniform norm tail prove the assertion for <span class=\"math\" data-tex=\"\\(\\omega\\)\">\\(\\omega\\)<\/span>. Transport through the normal core chart preserves that predual norm.<\/p>\n<p>Choose a nonnegative bounded compactly supported scalar function <span class=\"math\" data-tex=\"\\(g\\)\">\\(g\\)<\/span> with <span class=\"math\" data-tex=\"\\(\\int g(s)ds=1\\)\">\\(\\int g(s)ds=1\\)<\/span>, supported sufficiently close to zero that\n<span class=\"math display\" data-tex=\"\\[\n \\omega_g=\\int g(s)(\\omega\\circ\\theta_s)ds,\n \\qquad \\|\\omega_g-\\omega\\|&lt;\\varepsilon.\n \\tag{WCH15}\n\\]\">\\[\n \\omega_g=\\int g(s)(\\omega\\circ\\theta_s)ds,\n \\qquad \\|\\omega_g-\\omega\\|&lt;\\varepsilon.\n \\tag{WCH15}\n\\]<\/span>\nThis is a Bochner integral in the predual: norm-continuity, compact support and boundedness give its existence. For every coordinate <span class=\"math\" data-tex=\"\\(\\kappa_j\\)\">\\(\\kappa_j\\)<\/span>, including the limit one, let <span class=\"math\" data-tex=\"\\(\\mu_j(B)=\\omega(\\kappa_j(1_B))\\)\">\\(\\mu_j(B)=\\omega(\\kappa_j(1_B))\\)<\/span>. These are finite measures of total mass <span class=\"math\" data-tex=\"\\(\\mu_j(\\mathbb R)=\\omega(e_j)\\le\\omega(1)\\)\">\\(\\mu_j(\\mathbb R)=\\omega(e_j)\\le\\omega(1)\\)<\/span>, with <span class=\"math\" data-tex=\"\\(e_\\infty=e\\)\">\\(e_\\infty=e\\)<\/span>. They vanish on Lebesgue-null sets by normality. Equivariance and nonnegative scalar interchange give\n<span class=\"math display\" data-tex=\"\\[\n \\begin{aligned}\n \\omega_g(\\kappa_j(1_B))\n &amp;=\\int g(s)\\int 1_B(q+s)\\,d\\mu_j(q)\\,ds\\\\\n &amp;\\le\\|g\\|_\\infty\\,|B|\\,\\omega(1).\n \\end{aligned}\\tag{WCH16}\n\\]\">\\[\n \\begin{aligned}\n \\omega_g(\\kappa_j(1_B))\n &amp;=\\int g(s)\\int 1_B(q+s)\\,d\\mu_j(q)\\,ds\\\\\n &amp;\\le\\|g\\|_\\infty\\,|B|\\,\\omega(1).\n \\end{aligned}\\tag{WCH16}\n\\]<\/span>\nBoth measures in the interchange are sigma-finite; one is finite and the other is Lebesgue measure. Thus\n<span class=\"math display\" data-tex=\"\\[\n \\sup_j\\mu_j(B)\\le\\varepsilon+\\|g\\|_\\infty\\omega(1)|B|.\n \\tag{WCH17}\n\\]\">\\[\n \\sup_j\\mu_j(B)\\le\\varepsilon+\\|g\\|_\\infty\\omega(1)|B|.\n \\tag{WCH17}\n\\]<\/span>\nFor every prescribed bound <span class=\"math\" data-tex=\"\\(\\delta&gt;0\\)\">\\(\\delta&gt;0\\)<\/span>, first choose <span class=\"math\" data-tex=\"\\(\\varepsilon&lt;\\delta/2\\)\">\\(\\varepsilon&lt;\\delta/2\\)<\/span>, then make <span class=\"math\" data-tex=\"\\(|B|&lt;\\delta/(2\\|g\\|_\\infty\\omega(1))\\)\">\\(|B|&lt;\\delta/(2\\|g\\|_\\infty\\omega(1))\\)<\/span>. The zero functional needs no estimate. This proves uniform absolute continuity of the entire family of scalar spectral measures. It is the extra conclusion furnished by homogeneity; strong resolvent convergence alone does not imply it.<\/p>\n<p>If <span class=\"math\" data-tex=\"\\(v\\in C_c(\\mathbb R)\\)\">\\(v\\in C_c(\\mathbb R)\\)<\/span>, the scalar function <span class=\"math\" data-tex=\"\\(x\\mapsto v(-\\log x)\\)\">\\(x\\mapsto v(-\\log x)\\)<\/span> on <span class=\"math\" data-tex=\"\\((0,\\infty)\\)\">\\((0,\\infty)\\)<\/span>, extended by zero at zero, belongs to <span class=\"math\" data-tex=\"\\(C_0([0,\\infty))\\)\">\\(C_0([0,\\infty))\\)<\/span>. Strong resolvent convergence therefore gives <span class=\"math\" data-tex=\"\\(\\kappa_n(v)\\to\\kappa(v)\\)\">\\(\\kappa_n(v)\\to\\kappa(v)\\)<\/span> strongly-star. The functional-calculus step has an explicit approximation proof. Extend <span class=\"math\" data-tex=\"\\(f(x)=v(-\\log x)\\)\">\\(f(x)=v(-\\log x)\\)<\/span> by zero on <span class=\"math\" data-tex=\"\\(( -\\infty,0]\\)\">\\(( -\\infty,0]\\)<\/span>; compact support of <span class=\"math\" data-tex=\"\\(v\\)\">\\(v\\)<\/span> makes <span class=\"math\" data-tex=\"\\(f\\in C_0(\\mathbb R)\\)\">\\(f\\in C_0(\\mathbb R)\\)<\/span>. The Cayley unitaries <span class=\"math\" data-tex=\"\\(U_n=1-2i(h_n+i)^{-1}\\)\">\\(U_n=1-2i(h_n+i)^{-1}\\)<\/span> converge strongly to <span class=\"math\" data-tex=\"\\(U=1-2i(h+i)^{-1}\\)\">\\(U=1-2i(h+i)^{-1}\\)<\/span>. Their adjoints converge strongly too, since <span class=\"math\" data-tex=\"\\((U_n^*-U^*)\\xi=U_n^*(U-U_n)U^*\\xi\\)\">\\((U_n^*-U^*)\\xi=U_n^*(U-U_n)U^*\\xi\\)<\/span>. The Cayley coordinate <span class=\"math\" data-tex=\"\\(x\\mapsto(x-i)/(x+i)\\)\">\\(x\\mapsto(x-i)/(x+i)\\)<\/span> transports <span class=\"math\" data-tex=\"\\(f\\)\">\\(f\\)<\/span> to a continuous circle function <span class=\"math\" data-tex=\"\\(\\widehat f\\)\">\\(\\widehat f\\)<\/span> with <span class=\"math\" data-tex=\"\\(\\widehat f(1)=0\\)\">\\(\\widehat f(1)=0\\)<\/span>. The <a href=\"../courses/OA-FLOW/OA-FLOW-SF.html#oa-flow.sf.sb1\">proved Fejér approximation and unitary calculus<\/a> approximate <span class=\"math\" data-tex=\"\\(\\widehat f\\)\">\\(\\widehat f\\)<\/span> uniformly by Laurent polynomials. Each polynomial in <span class=\"math\" data-tex=\"\\(U_n,U_n^*\\)\">\\(U_n,U_n^*\\)<\/span> converges strongly-star, and the uniform approximation bound is independent of <span class=\"math\" data-tex=\"\\(n\\)\">\\(n\\)<\/span>. Consequently <span class=\"math\" data-tex=\"\\(f(h_n)=\\widehat f(U_n)\\to\\widehat f(U)=f(h)\\)\">\\(f(h_n)=\\widehat f(U_n)\\to\\widehat f(U)=f(h)\\)<\/span> strongly-star, which is exactly the assertion just used. Bounded strong convergence in a faithful normal representation also gives convergence for every normal positive seminorm: express that functional as a summable vector series and control its tail by the common operator bound.<\/p>\n<p>Support convergence gives <span class=\"math\" data-tex=\"\\(\\mu_n(\\mathbb R)=\\omega(e_n)\\to\\omega(e)=\\mu(\\mathbb R)\\)\">\\(\\mu_n(\\mathbb R)=\\omega(e_n)\\to\\omega(e)=\\mu(\\mathbb R)\\)<\/span>. The measures are therefore eventually tight. Given <span class=\"math\" data-tex=\"\\(\\varepsilon&gt;0\\)\">\\(\\varepsilon&gt;0\\)<\/span>, choose <span class=\"math\" data-tex=\"\\(0\\le v\\le1\\)\">\\(0\\le v\\le1\\)<\/span> in <span class=\"math\" data-tex=\"\\(C_c\\)\">\\(C_c\\)<\/span> with\n<span class=\"math\" data-tex=\"\\(\\mu(v)&gt;\\mu(\\mathbb R)-\\varepsilon\\)\">\\(\\mu(v)&gt;\\mu(\\mathbb R)-\\varepsilon\\)<\/span>. Increasing compact cutoffs provide such a function, including when <span class=\"math\" data-tex=\"\\(\\mu=0\\)\">\\(\\mu=0\\)<\/span>. For all sufficiently large <span class=\"math\" data-tex=\"\\(n\\)\">\\(n\\)<\/span>, the preceding functional-calculus convergence gives\n<span class=\"math\" data-tex=\"\\(\\mu_n(v)&gt;\\mu(v)-\\varepsilon\\)\">\\(\\mu_n(v)&gt;\\mu(v)-\\varepsilon\\)<\/span>, while\n<span class=\"math\" data-tex=\"\\(\\mu_n(\\mathbb R)&lt;\\mu(\\mathbb R)+\\varepsilon\\)\">\\(\\mu_n(\\mathbb R)&lt;\\mu(\\mathbb R)+\\varepsilon\\)<\/span>.\nIf <span class=\"math\" data-tex=\"\\(\\operatorname{supp}v\\subset[-R,R]\\)\">\\(\\operatorname{supp}v\\subset[-R,R]\\)<\/span>, then\n<span class=\"math display\" data-tex=\"\\[\n \\mu_n(\\mathbb R\\setminus[-R,R])&lt;3\\varepsilon.\n \\tag{WCH18}\n\\]\">\\[\n \\mu_n(\\mathbb R\\setminus[-R,R])&lt;3\\varepsilon.\n \\tag{WCH18}\n\\]<\/span>\nThe limit measure satisfies the same bound. Only this eventual estimate is needed.<\/p>\n<p>This also proves the stated automatic support convergence when <span class=\"math\" data-tex=\"\\(e=1\\)\">\\(e=1\\)<\/span>, without assuming it in advance. For every <span class=\"math\" data-tex=\"\\(\\omega\\in C_*^+\\)\">\\(\\omega\\in C_*^+\\)<\/span>, choose a compact cutoff with\n<span class=\"math\" data-tex=\"\\(\\omega(\\kappa(v))&gt;\\omega(1)-\\varepsilon\\)\">\\(\\omega(\\kappa(v))&gt;\\omega(1)-\\varepsilon\\)<\/span>. Since\n<span class=\"math\" data-tex=\"\\(0\\le\\kappa_n(v)\\le e_n\\)\">\\(0\\le\\kappa_n(v)\\le e_n\\)<\/span>, convergence on this continuous function gives\n<span class=\"math\" data-tex=\"\\(\\limsup_n\\omega(1-e_n)\\le\\varepsilon\\)\">\\(\\limsup_n\\omega(1-e_n)\\le\\varepsilon\\)<\/span>.\nLet <span class=\"math\" data-tex=\"\\(\\varepsilon\\downarrow0\\)\">\\(\\varepsilon\\downarrow0\\)<\/span>. Testing vector functionals proves <span class=\"math\" data-tex=\"\\(e_n\\to1\\)\">\\(e_n\\to1\\)<\/span> strongly, so the preceding tightness argument applies.<\/p>\n<p>Now fix <span class=\"math\" data-tex=\"\\(f\\in L^\\infty\\)\">\\(f\\in L^\\infty\\)<\/span>, represented with <span class=\"math\" data-tex=\"\\(|f|\\le K\\)\">\\(|f|\\le K\\)<\/span>. On <span class=\"math\" data-tex=\"\\([-R,R]\\)\">\\([-R,R]\\)<\/span> approximate its values by a finite grid to obtain a simple function within <span class=\"math\" data-tex=\"\\(\\eta\\)\">\\(\\eta\\)<\/span> uniformly. In each of its finitely many measurable level sets choose a compact subset; Lebesgue inner regularity makes the total discarded measure as small as desired. These compact sets are disjoint. Choose disjoint bounded open neighborhoods and continuous bump functions equal to one on the compact sets. The finite sum of the simple values times these bumps is a <span class=\"math\" data-tex=\"\\(v\\in C_c(\\mathbb R)\\)\">\\(v\\in C_c(\\mathbb R)\\)<\/span> with <span class=\"math\" data-tex=\"\\(|v|\\le K\\)\">\\(|v|\\le K\\)<\/span>, agreeing with the simple function on their union. Consequently <span class=\"math\" data-tex=\"\\(|f-v|\\le\\eta\\)\">\\(|f-v|\\le\\eta\\)<\/span> off a measurable exceptional set <span class=\"math\" data-tex=\"\\(B\\subset[-R,R]\\)\">\\(B\\subset[-R,R]\\)<\/span>, and <span class=\"math\" data-tex=\"\\(|B|\\)\">\\(|B|\\)<\/span> is arbitrarily small.<\/p>\n<p>Equations (WCH17)–(WCH18) give, uniformly for sufficiently large <span class=\"math\" data-tex=\"\\(n\\)\">\\(n\\)<\/span> and for the limit,\n<span class=\"math display\" data-tex=\"\\[\n \\begin{aligned}\n \\|\\kappa_n(f-v)\\|_\\omega^2\n &amp;=\\int|f-v|^2d\\mu_n\\\\\n &amp;\\le\\eta^2\\omega(1)+4K^2\\mu_n(B)\n          +4K^2\\mu_n(\\mathbb R\\setminus[-R,R]).\n \\end{aligned}\\tag{WCH19}\n\\]\">\\[\n \\begin{aligned}\n \\|\\kappa_n(f-v)\\|_\\omega^2\n &amp;=\\int|f-v|^2d\\mu_n\\\\\n &amp;\\le\\eta^2\\omega(1)+4K^2\\mu_n(B)\n          +4K^2\\mu_n(\\mathbb R\\setminus[-R,R]).\n \\end{aligned}\\tag{WCH19}\n\\]<\/span>\nHere <span class=\"math\" data-tex=\"\\(\\|x\\|_\\omega=\\omega(x^*x)^{1/2}\\)\">\\(\\|x\\|_\\omega=\\omega(x^*x)^{1/2}\\)<\/span>. First choose the tail bound, then the exceptional measure, then <span class=\"math\" data-tex=\"\\(\\eta\\)\">\\(\\eta\\)<\/span>. The right side can be made arbitrarily small. The triangle inequality and the already proved convergence for <span class=\"math\" data-tex=\"\\(v\\)\">\\(v\\)<\/span> prove convergence for <span class=\"math\" data-tex=\"\\(f\\)\">\\(f\\)<\/span>. Apply the same argument to <span class=\"math\" data-tex=\"\\(\\overline f\\)\">\\(\\overline f\\)<\/span> for the adjoint seminorms. This proves (WCH14) with all cutoffs and all normal functionals accounted for.<\/p>\n<p><strong>Why the support condition is necessary.<\/strong> In the scalar core of <a href=\"../courses/OA-FLOW/OA-FLOW-CORE.html#core-9\">CORE9<\/a>, use the positive Fourier coordinate <span class=\"math\" data-tex=\"\\(p\\)\">\\(p\\)<\/span>:\n<span class=\"math display\" data-tex=\"\\[\n C=L^\\infty(\\mathbb R,dp),\\qquad\n \\theta_s f(p)=f(p-s),\\qquad\n \\tau(f)=\\frac1{2\\pi}\\int e^{-p}f(p)\\,dp.\n\\]\">\\[\n C=L^\\infty(\\mathbb R,dp),\\qquad\n \\theta_s f(p)=f(p-s),\\qquad\n \\tau(f)=\\frac1{2\\pi}\\int e^{-p}f(p)\\,dp.\n\\]<\/span>\nThe finite scalar weights <span class=\"math\" data-tex=\"\\(\\varphi_n(1)=1/n\\)\">\\(\\varphi_n(1)=1/n\\)<\/span> have densities\n<span class=\"math display\" data-tex=\"\\[\n h_n(p)=e^p/n,\\qquad h(p)=0,\\qquad\n e_n=1,\\quad e=0. \\tag{WCH14a}\n\\]\">\\[\n h_n(p)=e^p/n,\\qquad h(p)=0,\\qquad\n e_n=1,\\quad e=0. \\tag{WCH14a}\n\\]<\/span>\nEvery <span class=\"math\" data-tex=\"\\(h_n\\)\">\\(h_n\\)<\/span> is positive, faithful and homogeneous, and its full multiplication domain is dense by compact truncation. The zero limit is the density of the zero normal semifinite weight. On <span class=\"math\" data-tex=\"\\(L^2(\\mathbb R,dp)\\)\">\\(L^2(\\mathbb R,dp)\\)<\/span>, the resolvent multipliers\n<span class=\"math\" data-tex=\"\\((e^p/n-i)^{-1}\\)\">\\((e^p/n-i)^{-1}\\)<\/span> converge pointwise to <span class=\"math\" data-tex=\"\\(i\\)\">\\(i\\)<\/span>, and their absolute values are at most one. Scalar dominated convergence against each squared Hilbert vector proves strong resolvent convergence to zero. Nevertheless\n<span class=\"math display\" data-tex=\"\\[\n \\kappa_n(f)(p)=f(\\log n-p),\\qquad\n \\kappa_0(f)=0,\\qquad\n \\kappa_n(1)-\\kappa_0(1)=1. \\tag{WCH14b}\n\\]\">\\[\n \\kappa_n(f)(p)=f(\\log n-p),\\qquad\n \\kappa_0(f)=0,\\qquad\n \\kappa_n(1)-\\kappa_0(1)=1. \\tag{WCH14b}\n\\]<\/span>\nThus even positive homogeneous measurable densities do not give the all-<span class=\"math\" data-tex=\"\\(L^\\infty\\)\">\\(L^\\infty\\)<\/span> conclusion when their supports fail to converge. The measurability follows also from their finite functional masses in <a href=\"../courses/OA-FLOW/OA-FLOW-MGI.html#gi-finite-cut\">MGI1<\/a>.<\/p>\n<p>The loss is visible in one normal vector functional. Take the unit vector\n<span class=\"math\" data-tex=\"\\(\\xi=1_{[0,1]}\\)\">\\(\\xi=1_{[0,1]}\\)<\/span> and set\n<span class=\"math\" data-tex=\"\\(\\mu_n(B)=\\langle\\kappa_n(1_B)\\xi,\\xi\\rangle\\)\">\\(\\mu_n(B)=\\langle\\kappa_n(1_B)\\xi,\\xi\\rangle\\)<\/span>.\nSubstitution <span class=\"math\" data-tex=\"\\(q=\\log n-p\\)\">\\(q=\\log n-p\\)<\/span> gives\n<span class=\"math display\" data-tex=\"\\[\n d\\mu_n(q)=1_{[\\log n-1,\\log n]}(q)\\,dq,\\qquad\n \\mu_n(\\mathbb R)=1,\\qquad \\mu_0=0. \\tag{WCH14c}\n\\]\">\\[\n d\\mu_n(q)=1_{[\\log n-1,\\log n]}(q)\\,dq,\\qquad\n \\mu_n(\\mathbb R)=1,\\qquad \\mu_0=0. \\tag{WCH14c}\n\\]<\/span>\nEvery compact coordinate set eventually has zero mass, while total mass stays one. Uniform absolute continuity (WCH17) still holds; tightness fails. These are vector spectral measures, not the canonical core trace.<\/p>\n<p><a class=\"figure-link\" href=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/support-continuity.png\" target=\"_blank\" rel=\"noopener\"><img src=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/support-continuity.png\" alt=\"Strong resolvent convergence to zero and the spectral mass retained by the nonzero supports.\" /><span>Open figure at full size<\/span><\/a><\/p>\n<p><em>Figure 4.<\/em> The left panel shows the exact bounded multipliers <span class=\"math\" data-tex=\"\\((1+e^p/n)^{-1}\\)\">\\((1+e^p/n)^{-1}\\)<\/span> on a finite window; their strong limit is <span class=\"math\" data-tex=\"\\(1\\)\">\\(1\\)<\/span>. The right panel shows the exact vector spectral measures (WCH14c), each of mass one on a translated unit interval, while the zero weight has mass zero. The full convergence proof is dominated convergence above, not a uniform estimate on the displayed window. Original <a href=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/render_support_continuity.py\">renderer<\/a>, <a href=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/support-continuity.json\">exact data<\/a>, <a href=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/support-continuity.svg\">editable SVG<\/a> and <a href=\"../courses/OA-FLOW/assets/canonical-cocycle-sections/TERMS.md\">terms<\/a>.<\/p>\n","source":"docs/courses/OA-FLOW/src/OA-FLOW-WCH.md","start_offset":10820,"end_offset":20884,"label":null,"extraction_boundary":"all_numbered_statements_in_bound_passage"},"a122c3eb418b9ef13b7b955c82dc201fca6e6327e06b38cff85152fbc1965d59":{"markdown":"**Exercise 4.1 — introductory: the ideal and quotient components.** Let \\(A=M_2(\\mathbb C)\\oplus\\mathbb C\\), \\(I=0\\oplus\\mathbb C\\), and \\(B=M_2(\\mathbb C)\\). Describe the closed quasi-state face and its complement. For a self-adjoint \\(x\\in B\\), compute the lift (3.3) and its norm.","html":"<p><strong>Exercise 4.1 — introductory: the ideal and quotient components.<\/strong> Let <span class=\"math\" data-tex=\"\\(A=M_2(\\mathbb C)\\oplus\\mathbb C\\)\">\\(A=M_2(\\mathbb C)\\oplus\\mathbb C\\)<\/span>, <span class=\"math\" data-tex=\"\\(I=0\\oplus\\mathbb C\\)\">\\(I=0\\oplus\\mathbb C\\)<\/span>, and <span class=\"math\" data-tex=\"\\(B=M_2(\\mathbb C)\\)\">\\(B=M_2(\\mathbb C)\\)<\/span>. Describe the closed quasi-state face and its complement. For a self-adjoint <span class=\"math\" data-tex=\"\\(x\\in B\\)\">\\(x\\in B\\)<\/span>, compute the lift (3.3) and its norm.<\/p>\n","source":"docs/courses/OA-FOUND-REMAINDER/src/split-faces-and-semicontinuous-quotient-lifts.md","start_offset":12362,"end_offset":12647,"label":"Exercise 4.1","extraction_boundary":"numbered_statement_boundary"},"a18a9882c97233816eade92ac6036f6c84fe643b9db52958699e6dce5bb26d08":{"markdown":"In the product from Section 4, let \\(q_n\\) be rank one in \\(M_{3^n}\\), and let \\(r_n\\) have rank \\(3^{n-1}\\). Determine the quotient images of \\(q=(q_n)\\) and \\(r=(r_n)\\), their operator norms when nonzero, and their quotient trace values.","html":"<p>In the product from Section 4, let <span class=\"math\" data-tex=\"\\(q_n\\)\">\\(q_n\\)<\/span> be rank one in <span class=\"math\" data-tex=\"\\(M_{3^n}\\)\">\\(M_{3^n}\\)<\/span>, and let <span class=\"math\" data-tex=\"\\(r_n\\)\">\\(r_n\\)<\/span> have rank <span class=\"math\" data-tex=\"\\(3^{n-1}\\)\">\\(3^{n-1}\\)<\/span>. Determine the quotient images of <span class=\"math\" data-tex=\"\\(q=(q_n)\\)\">\\(q=(q_n)\\)<\/span> and <span class=\"math\" data-tex=\"\\(r=(r_n)\\)\">\\(r=(r_n)\\)<\/span>, their operator norms when nonzero, and their quotient trace values.<\/p>\n","source":"docs/courses/OA-FOUND-REMAINDER/src/finite-maximal-quotients.md","start_offset":9355,"end_offset":9594,"label":"Exercise 5.1","extraction_boundary":"registered_full_statement_exact_source_match"},"a1636b2e611d66b1cadcde7a3d189e7dfd5a811c207bc9d2ce00c95eb16fbb2b":{"markdown":"**Exercise 7.4** (medium; Unitaries with a gap in the spectrum). In a C\\*-algebra \\(A\\) with identity, let \\(u\\in U(A)\\) with \\(\\sigma(u)\\neq\\mathbb T\\). Prove that \\(u=\\exp(ih)\\) for some \\(h\\in A_h\\).","html":"<p><strong>Exercise 7.4<\/strong> (medium; Unitaries with a gap in the spectrum). In a C*-algebra <span class=\"math\" data-tex=\"\\(A\\)\">\\(A\\)<\/span> with identity, let <span class=\"math\" data-tex=\"\\(u\\in U(A)\\)\">\\(u\\in U(A)\\)<\/span> with <span class=\"math\" data-tex=\"\\(\\sigma(u)\\neq\\mathbb T\\)\">\\(\\sigma(u)\\neq\\mathbb T\\)<\/span>. Prove that <span class=\"math\" data-tex=\"\\(u=\\exp(ih)\\)\">\\(u=\\exp(ih)\\)<\/span> for some <span class=\"math\" data-tex=\"\\(h\\in A_h\\)\">\\(h\\in A_h\\)<\/span>.<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/c-star-algebras-continuous-functional-calculus-automatic-continuity-positive-cones.md","start_offset":59313,"end_offset":59517,"label":"Exercise 7.4","extraction_boundary":"numbered_statement_boundary"},"a1cc3f7b3d49f75a109b666b350994d1969249aa1b62b523a66a37b5f3ff3602":{"markdown":"**Exercise 7.6** (medium; Self-adjointness through the norm). In a nontrivial C\\*-algebra \\(A\\) with identity, prove that \\(x\\in A\\) is self-adjoint exactly when \\(\\lim_{t\\to0}\\frac1t(\\|1+itx\\|-1)=0\\). (In the zero algebra \\(\\|1+itx\\|=0\\), so the quotient is \\(-1/t\\) and the statement fails.)","html":"<p><strong>Exercise 7.6<\/strong> (medium; Self-adjointness through the norm). In a nontrivial C*-algebra <span class=\"math\" data-tex=\"\\(A\\)\">\\(A\\)<\/span> with identity, prove that <span class=\"math\" data-tex=\"\\(x\\in A\\)\">\\(x\\in A\\)<\/span> is self-adjoint exactly when <span class=\"math\" data-tex=\"\\(\\lim_{t\\to0}\\frac1t(\\|1+itx\\|-1)=0\\)\">\\(\\lim_{t\\to0}\\frac1t(\\|1+itx\\|-1)=0\\)<\/span>. (In the zero algebra <span class=\"math\" data-tex=\"\\(\\|1+itx\\|=0\\)\">\\(\\|1+itx\\|=0\\)<\/span>, so the quotient is <span class=\"math\" data-tex=\"\\(-1/t\\)\">\\(-1/t\\)<\/span> and the statement fails.)<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/c-star-algebras-continuous-functional-calculus-automatic-continuity-positive-cones.md","start_offset":61289,"end_offset":61584,"label":"Exercise 7.6","extraction_boundary":"numbered_statement_boundary"},"a17621fe3e10e84c21b1a2ce18e98c12487c7dfff4998ff3399c9c74ed98de9e":{"markdown":"**Corollary 11.3** (The closed one-sided ideal generated by a positive element). Let \\(h\\in A_+\\) and let \\(\\mathfrak m\\) be the closed right ideal generated by \\(h\\).\n1. \\(x\\in\\mathfrak m\\) if and only if \\(\\|f_\\varepsilon(h)x-x\\|\\to0\\).\n2. If \\(xx^*\\leq\\lambda h\\) for some \\(\\lambda>0\\), then \\(x\\in\\mathfrak m\\), and \\(\\|x-f_\\varepsilon(h)x\\|\\leq\\frac12(\\lambda\\varepsilon)^{1/2}\\).\n3. \\(\\mathfrak m\\) is the closure of \\(hA\\), and it is also the closed right ideal generated by \\(h^\\alpha\\), for every \\(\\alpha>0\\).\n\nThe mirror statements hold for left ideals, with \\(x^*x\\leq\\lambda h\\) in (2).","html":"<p><strong>Corollary 11.3<\/strong> (The closed one-sided ideal generated by a positive element). Let <span class=\"math\" data-tex=\"\\(h\\in A_+\\)\">\\(h\\in A_+\\)<\/span> and let <span class=\"math\" data-tex=\"\\(\\mathfrak m\\)\">\\(\\mathfrak m\\)<\/span> be the closed right ideal generated by <span class=\"math\" data-tex=\"\\(h\\)\">\\(h\\)<\/span>.<\/p>\n<ol>\n<li><span class=\"math\" data-tex=\"\\(x\\in\\mathfrak m\\)\">\\(x\\in\\mathfrak m\\)<\/span> if and only if <span class=\"math\" data-tex=\"\\(\\|f_\\varepsilon(h)x-x\\|\\to0\\)\">\\(\\|f_\\varepsilon(h)x-x\\|\\to0\\)<\/span>.<\/li>\n<li>If <span class=\"math\" data-tex=\"\\(xx^*\\leq\\lambda h\\)\">\\(xx^*\\leq\\lambda h\\)<\/span> for some <span class=\"math\" data-tex=\"\\(\\lambda&gt;0\\)\">\\(\\lambda&gt;0\\)<\/span>, then <span class=\"math\" data-tex=\"\\(x\\in\\mathfrak m\\)\">\\(x\\in\\mathfrak m\\)<\/span>, and <span class=\"math\" data-tex=\"\\(\\|x-f_\\varepsilon(h)x\\|\\leq\\frac12(\\lambda\\varepsilon)^{1/2}\\)\">\\(\\|x-f_\\varepsilon(h)x\\|\\leq\\frac12(\\lambda\\varepsilon)^{1/2}\\)<\/span>.<\/li>\n<li><span class=\"math\" data-tex=\"\\(\\mathfrak m\\)\">\\(\\mathfrak m\\)<\/span> is the closure of <span class=\"math\" data-tex=\"\\(hA\\)\">\\(hA\\)<\/span>, and it is also the closed right ideal generated by <span class=\"math\" data-tex=\"\\(h^\\alpha\\)\">\\(h^\\alpha\\)<\/span>, for every <span class=\"math\" data-tex=\"\\(\\alpha&gt;0\\)\">\\(\\alpha&gt;0\\)<\/span>.<\/li>\n<\/ol>\n<p>The mirror statements hold for left ideals, with <span class=\"math\" data-tex=\"\\(x^*x\\leq\\lambda h\\)\">\\(x^*x\\leq\\lambda h\\)<\/span> in (2).<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/c-star-algebras-continuous-functional-calculus-automatic-continuity-positive-cones.md","start_offset":99881,"end_offset":100483,"label":"Corollary 11.3","extraction_boundary":"numbered_statement_boundary"},"a17ed9b8129a2a1e1bbda255ddbaa08caa5098246f94d64a0597493551ef754b":{"markdown":"**Example 11.7** (A nonclosed ideal need not be self-adjoint). In \\(A=C([-1,1])\\), put \\(f(t)=t+i|t|\\) and \\(I=fA\\). This is a two-sided algebraic ideal. For \\(t>0\\) the ratio \\(\\overline{f(t)}/f(t)\\) is \\(-i\\), and for \\(t<0\\) it is \\(i\\). A continuous function cannot have these two one-sided limits at \\(0\\), so \\(\\bar f\\notin I\\), although \\(f\\in I\\). Thus \\(I^*\\ne I\\).\n\nIts closure is precisely \\(J=\\{h\\in A:h(0)=0\\}\\). Certainly \\(I\\subseteq J\\). Conversely, for \\(h\\in J\\) and \\(\\varepsilon>0\\), set\n\\[\nh_\\varepsilon(t)=\\frac{h(t)|f(t)|^2}{|f(t)|^2+\\varepsilon}\n=f(t)\\frac{h(t)\\overline{f(t)}}{|f(t)|^2+\\varepsilon}\\in I.\n\\]\nGiven \\(\\delta>0\\), continuity of \\(h\\) makes \\(|h|<\\delta\\) on some interval about \\(0\\). There \\(|h-h_\\varepsilon|\\leq\\delta\\); on the compact complement, \\(|f|^2\\) has a positive minimum, so \\(h_\\varepsilon\\to h\\) uniformly. Hence \\(\\overline I=J\\). In particular \\(\\bar f\\in\\overline I\\setminus I\\), so \\(I\\) is not closed.\n\nTheorem 11.4 still supplies positive approximate identities inside \\(I\\) for its closure. It does not assert that \\(I\\) is self-adjoint. The closedness hypothesis in Theorem 15.1 is what permits a C*-algebra quotient. For related examples and the closed-ideal proof, see [Blackadar, *Operator Algebras*, II.5.2.1 and II.5.1.1, corrected author version](https://bruceblackadar.com/Mathematics/Cycr.pdf).","html":"<p><strong>Example 11.7<\/strong> (A nonclosed ideal need not be self-adjoint). In <span class=\"math\" data-tex=\"\\(A=C([-1,1])\\)\">\\(A=C([-1,1])\\)<\/span>, put <span class=\"math\" data-tex=\"\\(f(t)=t+i|t|\\)\">\\(f(t)=t+i|t|\\)<\/span> and <span class=\"math\" data-tex=\"\\(I=fA\\)\">\\(I=fA\\)<\/span>. This is a two-sided algebraic ideal. For <span class=\"math\" data-tex=\"\\(t&gt;0\\)\">\\(t&gt;0\\)<\/span> the ratio <span class=\"math\" data-tex=\"\\(\\overline{f(t)}/f(t)\\)\">\\(\\overline{f(t)}/f(t)\\)<\/span> is <span class=\"math\" data-tex=\"\\(-i\\)\">\\(-i\\)<\/span>, and for <span class=\"math\" data-tex=\"\\(t&lt;0\\)\">\\(t&lt;0\\)<\/span> it is <span class=\"math\" data-tex=\"\\(i\\)\">\\(i\\)<\/span>. A continuous function cannot have these two one-sided limits at <span class=\"math\" data-tex=\"\\(0\\)\">\\(0\\)<\/span>, so <span class=\"math\" data-tex=\"\\(\\bar f\\notin I\\)\">\\(\\bar f\\notin I\\)<\/span>, although <span class=\"math\" data-tex=\"\\(f\\in I\\)\">\\(f\\in I\\)<\/span>. Thus <span class=\"math\" data-tex=\"\\(I^*\\ne I\\)\">\\(I^*\\ne I\\)<\/span>.<\/p>\n<p>Its closure is precisely <span class=\"math\" data-tex=\"\\(J=\\{h\\in A:h(0)=0\\}\\)\">\\(J=\\{h\\in A:h(0)=0\\}\\)<\/span>. Certainly <span class=\"math\" data-tex=\"\\(I\\subseteq J\\)\">\\(I\\subseteq J\\)<\/span>. Conversely, for <span class=\"math\" data-tex=\"\\(h\\in J\\)\">\\(h\\in J\\)<\/span> and <span class=\"math\" data-tex=\"\\(\\varepsilon&gt;0\\)\">\\(\\varepsilon&gt;0\\)<\/span>, set\n<span class=\"math display\" data-tex=\"\\[\nh_\\varepsilon(t)=\\frac{h(t)|f(t)|^2}{|f(t)|^2+\\varepsilon}\n=f(t)\\frac{h(t)\\overline{f(t)}}{|f(t)|^2+\\varepsilon}\\in I.\n\\]\">\\[\nh_\\varepsilon(t)=\\frac{h(t)|f(t)|^2}{|f(t)|^2+\\varepsilon}\n=f(t)\\frac{h(t)\\overline{f(t)}}{|f(t)|^2+\\varepsilon}\\in I.\n\\]<\/span>\nGiven <span class=\"math\" data-tex=\"\\(\\delta&gt;0\\)\">\\(\\delta&gt;0\\)<\/span>, continuity of <span class=\"math\" data-tex=\"\\(h\\)\">\\(h\\)<\/span> makes <span class=\"math\" data-tex=\"\\(|h|&lt;\\delta\\)\">\\(|h|&lt;\\delta\\)<\/span> on some interval about <span class=\"math\" data-tex=\"\\(0\\)\">\\(0\\)<\/span>. There <span class=\"math\" data-tex=\"\\(|h-h_\\varepsilon|\\leq\\delta\\)\">\\(|h-h_\\varepsilon|\\leq\\delta\\)<\/span>; on the compact complement, <span class=\"math\" data-tex=\"\\(|f|^2\\)\">\\(|f|^2\\)<\/span> has a positive minimum, so <span class=\"math\" data-tex=\"\\(h_\\varepsilon\\to h\\)\">\\(h_\\varepsilon\\to h\\)<\/span> uniformly. Hence <span class=\"math\" data-tex=\"\\(\\overline I=J\\)\">\\(\\overline I=J\\)<\/span>. In particular <span class=\"math\" data-tex=\"\\(\\bar f\\in\\overline I\\setminus I\\)\">\\(\\bar f\\in\\overline I\\setminus I\\)<\/span>, so <span class=\"math\" data-tex=\"\\(I\\)\">\\(I\\)<\/span> is not closed.<\/p>\n<p>Theorem 11.4 still supplies positive approximate identities inside <span class=\"math\" data-tex=\"\\(I\\)\">\\(I\\)<\/span> for its closure. It does not assert that <span class=\"math\" data-tex=\"\\(I\\)\">\\(I\\)<\/span> is self-adjoint. The closedness hypothesis in Theorem 15.1 is what permits a C*-algebra quotient. For related examples and the closed-ideal proof, see <a href=\"https://bruceblackadar.com/Mathematics/Cycr.pdf\">Blackadar, <em>Operator Algebras<\/em>, II.5.2.1 and II.5.1.1, corrected author version<\/a>.<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/c-star-algebras-continuous-functional-calculus-automatic-continuity-positive-cones.md","start_offset":106931,"end_offset":108297,"label":"Example 11.7","extraction_boundary":"numbered_statement_boundary"},"a1b2bb6a83a3d14d054538879f0b9bfbd3f5ec1f0d9e7cb7f3a7031ff0fb80b5":{"markdown":"**Example 2.6.** For \\(\\lambda\\in c_0(I)\\), the diagonal operator \\(d_\\lambda\\) of Example 2.2 satisfies \\(|d_\\lambda|=d_{|\\lambda|}=\\sum_i|\\lambda_i|\\theta_{\\varepsilon_i,\\varepsilon_i}\\). By Theorem 2.3(c), \\(s(d_\\lambda)\\) lists the nonzero numbers \\(|\\lambda_i|\\) in decreasing order, with repetitions, followed by zeros. Only countably many \\(\\lambda_i\\) are nonzero because \\(\\lambda\\in c_0(I)\\).","html":"<p><strong>Example 2.6.<\/strong> For <span class=\"math\" data-tex=\"\\(\\lambda\\in c_0(I)\\)\">\\(\\lambda\\in c_0(I)\\)<\/span>, the diagonal operator <span class=\"math\" data-tex=\"\\(d_\\lambda\\)\">\\(d_\\lambda\\)<\/span> of Example 2.2 satisfies <span class=\"math\" data-tex=\"\\(|d_\\lambda|=d_{|\\lambda|}=\\sum_i|\\lambda_i|\\theta_{\\varepsilon_i,\\varepsilon_i}\\)\">\\(|d_\\lambda|=d_{|\\lambda|}=\\sum_i|\\lambda_i|\\theta_{\\varepsilon_i,\\varepsilon_i}\\)<\/span>. By Theorem 2.3(c), <span class=\"math\" data-tex=\"\\(s(d_\\lambda)\\)\">\\(s(d_\\lambda)\\)<\/span> lists the nonzero numbers <span class=\"math\" data-tex=\"\\(|\\lambda_i|\\)\">\\(|\\lambda_i|\\)<\/span> in decreasing order, with repetitions, followed by zeros. Only countably many <span class=\"math\" data-tex=\"\\(\\lambda_i\\)\">\\(\\lambda_i\\)<\/span> are nonzero because <span class=\"math\" data-tex=\"\\(\\lambda\\in c_0(I)\\)\">\\(\\lambda\\in c_0(I)\\)<\/span>.<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/compact-and-trace-class-operators-the-predual-of-b-h-and-the-operator-topologies.md","start_offset":43905,"end_offset":44309,"label":"Example 2.6","extraction_boundary":"numbered_statement_boundary"},"a16eb40a23953aebf8ddc638b8eebb8cfed45b8a8941333773d2cb47924ac261":{"markdown":"**Theorem 6.4** (Decomposition of a stonean space). Let \\(\\Omega\\) be stonean. There is exactly one partition of \\(\\Omega\\) into three clopen sets \\(\\Omega_1\\), \\(\\Omega_2\\), \\(\\Omega_3\\) with the following properties.\n\n1. \\(\\Omega_1\\) is hyperstonean.\n2. \\(\\Omega_2\\) contains a dense meager subset.\n3. Every meager subset of \\(\\Omega_3\\) is rare, and every Radon measure on \\(\\Omega_3\\) is concentrated on a closed rare subset of \\(\\Omega_3\\).\n\nMoreover, \\(\\Omega_1\\) is the closure of the union of all supports of normal measures on \\(\\Omega\\), and \\(\\Omega_2\\cup\\Omega_3\\) carries no normal measure other than \\(0\\). Any of the three parts may be empty; Section 9 gives stonean spaces with \\(\\Omega=\\Omega_2\\) and with \\(\\Omega=\\Omega_3\\).","html":"<p><strong>Theorem 6.4<\/strong> (Decomposition of a stonean space). Let <span class=\"math\" data-tex=\"\\(\\Omega\\)\">\\(\\Omega\\)<\/span> be stonean. There is exactly one partition of <span class=\"math\" data-tex=\"\\(\\Omega\\)\">\\(\\Omega\\)<\/span> into three clopen sets <span class=\"math\" data-tex=\"\\(\\Omega_1\\)\">\\(\\Omega_1\\)<\/span>, <span class=\"math\" data-tex=\"\\(\\Omega_2\\)\">\\(\\Omega_2\\)<\/span>, <span class=\"math\" data-tex=\"\\(\\Omega_3\\)\">\\(\\Omega_3\\)<\/span> with the following properties.<\/p>\n<ol>\n<li><span class=\"math\" data-tex=\"\\(\\Omega_1\\)\">\\(\\Omega_1\\)<\/span> is hyperstonean.<\/li>\n<li><span class=\"math\" data-tex=\"\\(\\Omega_2\\)\">\\(\\Omega_2\\)<\/span> contains a dense meager subset.<\/li>\n<li>Every meager subset of <span class=\"math\" data-tex=\"\\(\\Omega_3\\)\">\\(\\Omega_3\\)<\/span> is rare, and every Radon measure on <span class=\"math\" data-tex=\"\\(\\Omega_3\\)\">\\(\\Omega_3\\)<\/span> is concentrated on a closed rare subset of <span class=\"math\" data-tex=\"\\(\\Omega_3\\)\">\\(\\Omega_3\\)<\/span>.<\/li>\n<\/ol>\n<p>Moreover, <span class=\"math\" data-tex=\"\\(\\Omega_1\\)\">\\(\\Omega_1\\)<\/span> is the closure of the union of all supports of normal measures on <span class=\"math\" data-tex=\"\\(\\Omega\\)\">\\(\\Omega\\)<\/span>, and <span class=\"math\" data-tex=\"\\(\\Omega_2\\cup\\Omega_3\\)\">\\(\\Omega_2\\cup\\Omega_3\\)<\/span> carries no normal measure other than <span class=\"math\" data-tex=\"\\(0\\)\">\\(0\\)<\/span>. Any of the three parts may be empty; Section 9 gives stonean spaces with <span class=\"math\" data-tex=\"\\(\\Omega=\\Omega_2\\)\">\\(\\Omega=\\Omega_2\\)<\/span> and with <span class=\"math\" data-tex=\"\\(\\Omega=\\Omega_3\\)\">\\(\\Omega=\\Omega_3\\)<\/span>.<\/p>\n","source":"docs/courses/foundations-of-von-neumann-algebras/src/abelian-operator-algebras.md","start_offset":115321,"end_offset":116066,"label":"Theorem 6.4","extraction_boundary":"numbered_statement_boundary"}});
